def finish(sections, lang):
    """Append the practice drills (shared, language-specific data) to the practice section."""
    for sec in sections:
        if sec["id"] == "practice" and not any(b[0] == "drill" for b in sec["blocks"]):
            sec["blocks"].extend(deriv_drills.drill_blocks(lang))
    return sections


